// Classify Jana's incoming mail and forward only client / lead / update
// emails to the command center. Personal mail, OTPs and automated notices are
// dropped here so they never reach GSD. Tune the two regexes below to taste.

const out = [];

for (const item of $input.all()) {
  const d = item.json;

  // -- Normalise sender --
  const fromRaw = d.From || d.from || (d.headers && d.headers.from) || '';
  const angle = String(fromRaw).match(/<([^>]+)>/);
  const fromEmail = (angle ? angle[1] : String(fromRaw)).trim().toLowerCase();
  const fromName = String(fromRaw).replace(/<[^>]+>/, '').replace(/"/g, '').trim() || null;

  const subject = d.Subject || d.subject || (d.headers && d.headers.subject) || '(no subject)';
  const bodyText = d.text || d.textPlain || d.snippet || '';
  const bodyHtml = d.html || d.textHtml || null;

  // -- Filter: skip automated / no-reply senders --
  const automated = /no-?reply|do-?not-?reply|mailer-daemon|postmaster|notifications?@|newsletter|unsubscribe@/i.test(fromEmail);

  // -- Filter: skip OTP / verification / 2FA mail --
  const probe = (subject + ' ' + bodyText.slice(0, 200));
  const otp = /\b(otp|one[- ]?time|verification|verify|security|login|sign[- ]?in)\b[^\n]*\bcode\b/i.test(probe)
           || /\bcode\b[^\n]*\b\d{4,8}\b/i.test(probe)
           || /\byour .*code is\b/i.test(probe)
           || /2fa|two[- ]?factor/i.test(probe);

  if (automated || otp) continue;

  out.push({
    json: {
      externalId: d.id || d.messageId || undefined,
      threadExternalId: d.threadId || undefined,
      fromEmail,
      fromName,
      to: d.To || d.to || $env.GSD_INBOX_ADDRESS || '',
      subject,
      bodyText: bodyText || '(no text body)',
      bodyHtml,
      receivedAt: d.date ? new Date(d.date).toISOString() : new Date().toISOString(),
    },
  });
}

return out;
